// PROB20-11 exact certificate for the final K=4 four-edge-matching class.
// active parities 00001111, close distances (2,2,2,2), neven=6.
// Exact finite folded-cube computation; no floating point, MILP, heuristic, or timeout inference.
// Symmetry dependency: completeness of normalized second d2-edge representatives
// (125,126),(125,189) is independently certified by archived d2 stabilizer certificates.
#include <bits/stdc++.h>
using namespace std; static const int N=2048,MAXC=512;
int fd(int a,int b){int w=__builtin_popcount((unsigned)(a^b));return min(w,12-w);}int par(int x){return __builtin_popcount((unsigned)x)&1;}
array<bitset<N>,N>balls;bitset<N>EVM,ODM;
pair<int,int>tri(int a,int b,int c){auto z=balls[a]&balls[b]&balls[c];return {(int)(z&EVM).count(),(int)(z&ODM).count()};}
bool low(pair<int,int>e,int x){auto t=tri(e.first,e.second,x);if(t==make_pair(0,0))return true;int p=par(e.first),d=fd(e.first,e.second);assert(d==2);auto hi=p?make_pair(6,4):make_pair(4,6);assert(t==hi);return false;}
long long ex3(const vector<int>&cs,const bitset<N>&half){bitset<N>c0,c1,c2,c3;for(int c:cs){bitset<N>carry=balls[c],t;t=c0^carry;carry=c0&carry;c0=t;t=c1^carry;carry=c1&carry;c1=t;t=c2^carry;carry=c2&carry;c2=t;t=c3^carry;carry=c3&carry;c3=t;assert(carry.none());}array<bitset<N>,4>p={c0,c1,c2,c3};long long h=0;for(int k=4;k<=(int)cs.size();k++){bitset<N>m=half;for(int b=0;b<4;b++)m&=((k>>b)&1)?p[b]:~p[b];h+=1LL*(k-1)*(k-2)*(k-3)/6*m.count();}return h;}
struct Edge{int i,j,y;};struct Keep{vector<int>a;int x,y,dE,dO,hE,hO;};
vector<Keep>run(pair<int,int>rep){vector<int>E={0,3,rep.first,rep.second};vector<int>O;for(int x=0;x<N;x++){if(par(x)!=1)continue;bool ok=true;for(int e:E)if(fd(x,e)!=5){ok=false;break;}if(ok)O.push_back(x);}int n=O.size();vector<int>xw(n);for(int i=0;i<n;i++)xw[i]=low({0,3},O[i])+low(rep,O[i]);vector<bitset<MAXC>>far(n);vector<Edge>d2;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){int d=fd(O[i],O[j]);if(d==6)far[i][j]=far[j][i]=1;else if(d==2){int y=0;for(int e:E)y+=low({O[i],O[j]},e);d2.push_back({i,j,y});}}
long long raw=0,bud=0;vector<Keep>kept;map<array<int,6>,long long>kp;int best=INT_MAX;array<int,6>bp{};
for(int q=0;q<(int)d2.size();q++){auto&a=d2[q];auto common=far[a.i]&far[a.j];for(int r=q+1;r<(int)d2.size();r++){auto&b=d2[r];if(!common[b.i]||!common[b.j])continue;raw++;int x=xw[a.i]+xw[a.j]+xw[b.i]+xw[b.j],y=a.y+b.y;int dE=4*x+6*y,dO=6*x+4*y;if(dE>28||dO>28)continue;bud++;vector<int>act=E;act.insert(act.end(),{O[a.i],O[a.j],O[b.i],O[b.j]});int hE=ex3(act,EVM),hO=ex3(act,ODM);int v=max(hE-(28-dE),hO-(28-dO));if(v<best){best=v;bp={x,y,dE,dO,hE,hO};}if(hE<=28-dE&&hO<=28-dO){kept.push_back({act,x,y,dE,dO,hE,hO});kp[{x,y,dE,dO,hE,hO}]++;}}}
if(rep==make_pair(125,126)){array<int,6>w={4,0,16,24,21,16};assert(n==400&&d2.size()==6800&&raw==1728400&&bud==151200&&kept.empty()&&best==12&&bp==w);}else{array<int,6>w={0,0,0,0,32,32};assert(rep==make_pair(125,189));assert(n==412&&d2.size()==7376&&raw==2041488&&bud==486048&&kept.empty()&&best==4&&bp==w);}cerr<<"rep "<<rep.first<<","<<rep.second<<" O="<<n<<" d2="<<d2.size()<<" raw="<<raw<<" bud="<<bud<<" kept="<<kept.size()<<" best="<<(bud?best:-1)<<" bp";if(bud)for(int z:bp)cerr<<" "<<z;cerr<<"\n";for(auto[p,c]:kp){cerr<<" pat";for(int z:p)cerr<<" "<<z;cerr<<" :"<<c<<"\n";}return kept;}
int main(){vector<int>B0;for(int x=0;x<N;x++)if(fd(0,x)<=3)B0.push_back(x);assert(B0.size()==299);for(int c=0;c<N;c++)for(int b:B0)balls[c].set(c^b);for(int x=0;x<N;x++)if(par(x)==0)EVM.set(x);ODM=~EVM;vector<Keep>all;for(auto r:{pair<int,int>{125,126},pair<int,int>{125,189}}){auto k=run(r);all.insert(all.end(),k.begin(),k.end());}assert(all.empty());cout<<"MATCHING4 2,2,2,2 CERTIFICATE PASSED\n";cout<<"CONCLUSION: canonical class (00001111; 2,2,2,2; neven=6) is impossible\n";}
